(() => {
  const T = window.__CITY_APP.trafficSystem, s = T.pedRoutes.stats;
  const { blockedAt, detourAt, ...rest } = s;
  const placed = T.peds.filter((p) => p.placed);
  const out = { ...rest, detourMs: +s.detourMs.toFixed(1), q: location.search, peds: placed.length,
    onDetourPieces: placed.filter((p) => p.route && (p.route.before || p.route.after)).length,
    onCrosswalks: placed.filter((p) => p.node).length, waiting: placed.filter((p) => p.waiting).length };
  console.log('[ride-check] ped-routes ' + JSON.stringify(out));
  if (!/peddetours=0/.test(location.search) && !(s.obstacles > 1000)) throw new Error('walkers got no furniture obstacles');
