(() => {
  const app = window.__CITY_APP, C = window.CITY, T = app.trafficSystem;
  const all = C.patioStats.sites.filter((s) => s.kind === 'sidewalk' && s.outerLine !== null && s.outerLine !== undefined);
  const s = all.find((p) => /OSSINGTON/.test(p.address)) || all.find((p) => /COLLEGE/.test(p.address)) || all[0];
  window.__patio = s;
  document.getElementById('btn-toggle-hud')?.click();
  // the walker 14 m along the sidewalk from it, then the camera above the curb, looking at the café
  const x = s.cx + s.tx * 14 - s.nx * 1.2, z = s.cz + s.tz * 14 - s.nz * 1.2;
  app.teleportTo(x, z, Math.atan2(-s.tx, -s.tz));
  const cam = [s.cx - s.nx * 9 + s.tx * 6, 9, s.cz - s.nz * 9 + s.tz * 6];
  app.cameraSystem.cinema = () => ({ pos: cam, look: [s.cx - s.nx * 1.5, 0.3, s.cz - s.nz * 1.5], fov: 55 });
  // its edge's sidewalk lines (built now if no one has walked there yet): the pieces of the outer line round it
  const edges = T.network.edges.filter((e) => {
    const t = Math.max(0, Math.min(e.len, (s.cx - e.sx) * e.dx + (s.cz - e.sz) * e.dz));
    return Math.hypot(e.sx + e.dx * t - s.cx, e.sz + e.dz * t - s.cz) < 20;
  });
  const lines = edges.flatMap((e) => T.pedRoutes.along(e).filter((w) => Math.hypot(w.ax + w.ux * w.len / 2 - s.cx, w.az + w.uz * w.len / 2 - s.cz) < 60 || w.before || w.after)
    .map((w) => ({ ax: +w.ax.toFixed(1), az: +w.az.toFixed(1), len: +w.len.toFixed(1), before: !!w.before, after: !!w.after,
      off: +(((w.ax - s.cx) * s.nx + (w.az - s.cz) * s.nz)).toFixed(2) })));
  console.log('[ride-check] patio ' + JSON.stringify({ address: s.address, x: +s.cx.toFixed(1), z: +s.cz.toFixed(1), length: s.length,
    depth: +s.depth.toFixed(2), outerLine: s.outerLine, candidates: all.length, lines }));
})()

