(() => {
  const app = window.__CITY_APP, T = app.trafficSystem, cm = app.controllerManager, P = cm.entities[cm.activeMode].position;
  const on = T.peds.filter((p) => p.placed && !p.node && !p.mid && p.route && (p.route.before || p.route.after));
  on.sort((a, b) => Math.hypot(a.x - P.x, a.z - P.z) - Math.hypot(b.x - P.x, b.z - P.z));
  const p = on[0];
  window.__follow = p || null;
  if (!p) { console.log('[ride-check] detour-follow none of ' + T.peds.filter((q) => q.placed).length); return; }
  // its line: the first piece of the chain (the straight line it leaves); the camera beside it, 8 m up
  let first = p.route; while (first.before) first = first.before;
  window.__line = first;
  app.cameraSystem.cinema = () => ({ pos: [p.x - first.uz * 7 - first.ux * 6, 7, p.z + first.ux * 7 - first.uz * 6], look: [p.x + first.ux * 2, 0.4, p.z + first.uz * 2], fov: 55 });
  const pieces = []; for (let t = first; t; t = t.after) pieces.push({ ax: +t.ax.toFixed(2), az: +t.az.toFixed(2), len: +t.len.toFixed(2) });
  console.log('[ride-check] detour-follow ' + JSON.stringify({ x: +p.x.toFixed(1), z: +p.z.toFixed(1), pieces }));
})()

