(async () => {
  const T = window.__CITY_APP.trafficSystem;
  const t0 = performance.now();
  for (;;) {
    const groups = new Map();
    for (const p of T.peds) {
      if (!p.placed || !p.node || Math.hypot(p.node.x - -1105, p.node.z - -345) > 45) continue;
      const k = p.node.x.toFixed(0) + ':' + p.node.z.toFixed(0) + ':' + p.side;
      (groups.get(k) || groups.set(k, { waiting: 0, reacting: 0, people: [] }).get(k)).people.push(p);
    }
    let best = null;
    for (const g of groups.values()) {
      g.waiting = g.people.filter((p) => p.waiting).length;
      g.reacting = g.people.filter((p) => p.waiting && p.walkAt > 0).length;
      if (g.reacting >= 2 && g.reacting === g.waiting && (!best || g.reacting > best.reacting)) best = g;
    }
    if (best) {
      window.__walkers = best.people;
      // (the camera turned onto them: on a phone's narrow view the corner's group is otherwise out of frame)
      const cx = best.people.reduce((a, p) => a + p.x, 0) / best.people.length, cz = best.people.reduce((a, p) => a + p.z, 0) / best.people.length;
      window.__CITY_APP.cameraSystem.cinema = () => ({ pos: [-1085, 9, -322], look: [cx, 0.5, cz], fov: 50 });
      break;
    }
    if (performance.now() - t0 > 100000) { console.log('[ride-check] walk-onset none in 100 s'); window.__walkers = []; return; }
    await new Promise((r) => setTimeout(r, 40));
  }
  console.log('[ride-check] walk-onset after ' + Math.round(performance.now() - t0) + ' ms: ' + window.__walkers.length + ' people');
})()

